   108|export function createTransientMessageId(prefix: string): string {
   109|  const cryptoRef = globalThis.crypto as { randomUUID?: () => string } | undefined;
   110|  if (cryptoRef?.randomUUID) {
   111|    return `${prefix}-${cryptoRef.randomUUID()}`;
   112|  }
   113|  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
