   116|/**
   117| * Sorts messages by their authoritative server timestamp and a stable ID tiebreaker.
   118| * Invalid/missing timestamps fall behind dated records without reordering equal IDs.
   119| */
   120|export function sortMessagesByCanonicalOrder<T extends { id: string; createdAt?: string | null; serverCreatedAt?: string | null }>(messages: readonly T[]): T[] {
   121|  return [...messages].sort((left: T, right: T): number => {
   122|    const leftTimestamp = left.serverCreatedAt ?? left.createdAt ?? '';
   123|    const rightTimestamp = right.serverCreatedAt ?? right.createdAt ?? '';
   124|    const leftTime = Date.parse(leftTimestamp);
   125|    const rightTime = Date.parse(rightTimestamp);
   126|    const leftValid = Number.isFinite(leftTime);
   127|    const rightValid = Number.isFinite(rightTime);
   128|
   129|    if (leftValid && rightValid && leftTime !== rightTime) return leftTime - rightTime;
   130|    if (leftValid !== rightValid) return leftValid ? -1 : 1;
   131|    return left.id.localeCompare(right.id);
   132|  });
   133|}
