   154|export function formatMessageDateLabel(value: string): string {
   155|  const date = new Date(value);
   156|  if (Number.isNaN(date.getTime())) {
   157|    return 'Recent';
   158|  }
   159|  const today = new Date();
   160|  const yesterday = new Date();
   161|  yesterday.setDate(today.getDate() - 1);
   162|  const dateKey = formatMessageDateKey(value);
   163|  if (dateKey === formatMessageDateKey(today.toISOString())) {
   164|    return 'Today';
   165|  }
   166|  if (dateKey === formatMessageDateKey(yesterday.toISOString())) {
   167|    return 'Yesterday';
   168|  }
   169|  return date.toLocaleDateString([], {
   170|    month: 'short',
   171|    day: 'numeric',
   172|    year: date.getFullYear() === today.getFullYear() ? undefined : 'numeric',
   173|  });
