   187|export function getAttachmentKindFromUpload(upload: IVXUploadInput): IVXMessage['attachmentKind'] {
   188|  const mime = upload.type?.toLowerCase() ?? '';
   189|  const name = upload.name.toLowerCase();
   190|  if (mime.startsWith('image/') || /\.(png|jpg|jpeg|gif|webp|heic)$/.test(name)) return 'image';
   191|  if (mime.startsWith('video/') || /\.(mp4|mov|webm|m4v)$/.test(name)) return 'video';
